-- 015_readiness_minutes.sql
--
-- محضر تأكيد جاهزية تقديم خدمة الإعاشة, for منى and for عرفات.
--
-- The ministry's own sheet, reproduced rather than restyled: a four column
-- ruled grid with pale green label cells, carrying no letterhead of ours.
--
-- Nearly every blank is settled before anyone opens it. The caterer's details
-- come from the caterer registry, the centre's from the centre and its primary
-- official, the company's licence and facility from org_settings (see 016),
-- the day and date from the clock, and the eight readiness answers are printed
-- constants. The company states its own signatory; the caterer adds a
-- signature and a stamp and nothing else.
--
-- Generated from src/config/standardForms.js, which stays the source of truth.
-- Regenerate rather than editing the JSON below by hand.
--
-- Run 016 first — without it the company's three blanks resolve to nothing.
--
-- Re-running is safe: it upserts on `key`, and templates the customer authored
-- (which have no key) are never touched.

INSERT INTO public.form_templates
  (key, title, description, category, definition,
   requires_signature, requires_attachment, is_standard, active, updated_at)
